"""Ingest labeled experimental measurements into PostgreSQL."""import mathimport pandas as pdfrom sqlalchemy import select, deletefrom co2_submission.loader import load_runsfrom co2_submission.deployment.database import (    Experiment,    ProcessMeasurement,    CO2Observation,    get_session_factory,)def to_json_value(value):    """Convert pandas/numpy values to JSON-compatible Python values."""    if pd.isna(value):        return None    value = float(value)    if not math.isfinite(value):        return None    return valuedef ingest_experiments(raw_dir):    """    Import all experiments using the existing project loader.    Each experiment is replaced transactionally, allowing safe    repeated ingestion without duplicate measurements.    """    runs = load_runs(raw_dir)    Session = get_session_factory()    summary = {}    with Session() as session:        for experiment_name, frame in runs.items():            with session.begin():                experiment = session.scalar(                    select(Experiment).where(                        Experiment.name == experiment_name                    )                )                if experiment is None:                    experiment = Experiment(name=experiment_name)                    session.add(experiment)                    session.flush()                else:                    session.execute(                        delete(CO2Observation).where(                            CO2Observation.experiment_id == experiment.id                        )                    )                    session.execute(                        delete(ProcessMeasurement).where(                            ProcessMeasurement.experiment_id == experiment.id                        )                    )                process_records = []                observation_records = []                for row_index, row in frame.iterrows():                    timestamp = pd.Timestamp(                        row["timestamp"]                    ).to_pydatetime()                    measurements = {                        column: to_json_value(row[column])                        for column in frame.columns                        if column != "timestamp"                    }                    process_records.append(                        ProcessMeasurement(                            experiment_id=experiment.id,                            row_index=int(row_index),                            timestamp=timestamp,                            measurements=measurements,                        )                    )                    observation_records.append(                        CO2Observation(                            experiment_id=experiment.id,                            row_index=int(row_index),                            timestamp=timestamp,                            location=f"L{int(row['label'])}",                            concentration=float(row["AT400"]),                        )                    )                session.add_all(process_records)                session.add_all(observation_records)                summary[experiment_name] = {                    "rows": len(frame),                    "observations": len(observation_records),                }    return summary